<?php require __DIR__.'/app/layout.php';$user=must_login();
$tab=(string)($_GET['status']??'');$params=[$user['id']];$sql='SELECT r.*,s.name AS room_name FROM reservations r JOIN rooms s ON s.id=r.room_id WHERE r.user_id=?';
if(in_array($tab,['approved','pending','cancelled','rejected'],true)){$sql.=' AND r.status=?';$params[]=$tab;}
$sql.=' ORDER BY booking_date DESC,start_time DESC';$rows=all_rows($sql,$params);
page_start('Mes réservations','mine');titlebar('Mon espace','Mes réservations','Consultez et gérez toutes vos réunions.'); ?>
<div class="d-flex flex-wrap align-items-center gap-2 mb-4"><a href="<?=h(url('reservation.php'))?>" class="btn btn-primary me-auto"><i class="bi bi-plus-circle me-2"></i>Nouvelle réservation</a><?php foreach([''=>'Toutes','approved'=>'Confirmées','pending'=>'En attente','cancelled'=>'Annulées','rejected'=>'Refusées'] as $s=>$name):?><a class="btn btn-sm <?= $tab===$s?'btn-primary':'btn-outline-secondary' ?>" href="<?=h(url('mesreservations.php?status='.$s))?>"><?=h($name)?></a><?php endforeach;?></div>
<div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Réunion</th><th>Salle</th><th>Date</th><th>Horaire</th><th>Participants</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold"><?=h($r['title'])?></td><td><?=h($r['room_name'])?></td><td><?=h($r['booking_date'])?></td><td><?=h(substr($r['start_time'],0,5).' – '.substr($r['end_time'],0,5))?></td><td><?=h($r['attendees'])?></td><td><?=pill($r['status'])?></td><td><div class="d-flex gap-2 align-items-center"><?php if(can_change($r)):?><a class="btn btn-sm btn-outline-primary" href="<?=h(url('reservation.php?id='.$r['id']))?>" title="Modifier"><i class="bi bi-pencil"></i></a><form method="post" action="<?=h(url('actions.php'))?>" data-confirm="Annuler cette réservation ?"><?=csrf_field()?><input type="hidden" name="action" value="reservation_cancel"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-sm btn-outline-danger" title="Annuler"><i class="bi bi-x-circle"></i></button></form><?php else:?><span class="muted">—</span><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7"><div class="empty-state"><i class="bi bi-calendar2-x"></i>Vous n’avez aucune réservation dans cette catégorie.</div></td></tr><?php endif;?></tbody></table></div></div>
<?php page_end();?>
